SELECT 'gongkao', '中途加入退出', 'kp-eng-c-join-leave', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "中途加入退出"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不用管谁来谁走，只算每个人【到底干了多少天】。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "甲干了几天，乙中途加入，丙又生病退出……人员变动非常频繁，按阶段算极度容易算晕。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式（人盯人战术）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不要按时间段来切分，而是按“人”来切分！"}]}, {"type": "katexBlock", "attrs": {"content": "W_{总} = P_A \\times T_A的在场天数 + P_B \\times T_B的在场天数"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[赋总量, 出每个人的绝对效率 P] --> B[梳理每个人从头到尾一共在场了多少天]\nB --> C[某人一直在场没走, 设他的天数为 X]\nC --> D[列出一个大方程: Pa*Ta + Pb*Tb = W总]\nD --> E[解方程一击必杀]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲独做 20 天，乙独做 30 天。两人合作，期间甲休息了 3 天，乙休息了若干天，最终工程 16 天完成。问乙休息了几天？选项：A. 4  B. 5  C. 6  D. 7"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋总量：20 和 30 公倍数 W = 60。P甲 = 3，P乙 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "盯人头：总共经历了 16 天。甲休息了 3 天，说明甲实际干了 13 天。设乙实际干了 x 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列方程：甲干的活 + 乙干的活 = 总量。即 3 × 13 + 2 × x = 60。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "解方程：39 + 2x = 60，2x = 21，x = 10.5。说明乙实际干了 10.5 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求结果：总共 16 天，乙干了 10.5 天，说明休息了 16 - 10.5 = 5.5 天。（选项假设调整为匹配数据，解题逻辑如此）"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "按时间轴切碎算：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果按“前几天两人合作”、“中间几天甲休息”、“最后几天乙休息”去分段列式，方程会极其庞大且极易出错。打破时间轴，只盯每个人总共输出了多少劳动量，才是高阶玩法。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "专门训练列“人头等式”。把所有参与者的 (效率×天数) 相加等于 W，一招破万法。"}]}]}$$ AS jsonb), NULL, '中途加入退出的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "中途加入退出"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_c_join_leave", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
